with base as (select id, name, country, city, segment, signup_date, credit_limit, age, if(is_active, 'Yes', 'No') as is_active_label, coalesce(city, 'OTHER') as city_clean from customers where segment is not null), filtered as (select id, country, segment, signup_date, is_active_label, city_clean, round(age, 2) as age_rounded, coalesce(city, 'UNKNOWN') as city_filled from base where city = 'Bangkok'), enriched as (select *, lead(age_rounded, 1) over (partition by month(signup_date), country order by signup_date asc, id asc) as next_age_rounded, lag(age_rounded, 1) over (partition by country order by age_rounded asc, id asc) as prev_age_rounded from filtered), enriched_customers as (select *, sum(prev_age_rounded) over (partition by segment order by age_rounded asc, id asc rows between unbounded preceding and current row) as running_sum_prev_age_rounded, count(prev_age_rounded) over (partition by segment order by age_rounded asc, id asc rows between unbounded preceding and current row) as running_count_prev_age_rounded, max(prev_age_rounded) over (partition by segment order by age_rounded asc, id asc rows between unbounded preceding and current row) as running_max_prev_age_rounded from enriched), filtered_customers as (select *, date_format(signup_date, 'yyyy-MM') as signup_date_label from enriched_customers where running_sum_prev_age_rounded > 190), filtered_customers_2 as (select *, case when segment = 'Consumer' then 1 else 0 end as is_consumer, coalesce(prev_age_rounded, 0) as prev_age_rounded_filled, coalesce(segment, 'DIRECT') as segment_clean from filtered_customers where signup_date >= date '2023-09-12' and segment is not null) select date_trunc('year', signup_date) as year_start, country, date_trunc('month', signup_date) as activity_month, percentile_approx(age_rounded, array(0.25, 0.5, 0.75)) as age_rounded_quartiles, round(avg(prev_age_rounded_filled), 2) as avg_prev_age_rounded_filled from filtered_customers_2 group by 1, 2, 3 order by year_start desc;
